def min_time_to_visit_chairs(n, s, e, x, a, b, c, d):
    # Initialize a DP table where dp[i][j] represents the minimum time to visit chairs 1 to i with Scott in state j
    dp = [[float('inf')] * 2 for _ in range(n + 1)]
    dp[0][0] = 0  # Base case: no time to visit 0 chairs with Scott in any state
    dp[0][1] = 0  # Base case: no time to visit 0 chairs with Scott in any state

    for i in range(1, n + 1):
        for j in range(2):
            for k in range(1, n + 1):
                for l in range(2):
                    if i == s and (k != e or j != l):
                        continue
                    if i == e and (k != s or j != l):
                        continue
                    if i == k and j == l:
                        continue

                    cost = 0
                    if j == 0:  # Scott is small
                        if k < i:
                            cost = c[i - 1] + b[k - 1]
                        else:
                            cost = d[i - 1] + a[k - 1]
                    else:  # Scott is large
                        if k < i:
                            cost = d[i - 1] + b[k - 1]
                        else:
