                    if k < i:
                        jump_time = x[i - 1] - x[k - 1] + cost
                    else:
                        jump_time = x[k - 1] - x[i - 1] + cost

                    dp[i][j] = min(dp[i][j], dp[k - 1][l] + jump_time)

    return min(dp[n][0], dp[n][1])

